const ASSETS={"/index.html":{"body":"<!doctype html>\n<html lang=\"en\">\n<head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Jeff Outreach Engine | Company Review</title><link rel=\"stylesheet\" href=\"./styles.css\"></head>\n<body>\n<header class=\"topbar\"><div><p class=\"eyebrow\">Jeff Outreach Engine</p><h1>Company Review</h1></div><div class=\"summary\"><div><strong id=\"readyCount\">0</strong><span>Ready for Jeff</span></div><div><strong id=\"researchCount\">0</strong><span>In review</span></div></div></header>\n<main>\n<section class=\"connection\"><p id=\"connection\" role=\"status\">Connecting...</p><button id=\"refresh\">Refresh</button><button id=\"demo\">Practice mode</button><button id=\"exitDemo\" hidden>Exit practice</button></section><p id=\"notice\" role=\"alert\"></p>\n<div class=\"toolbar\"><button id=\"addOpportunity\">Add company</button><label>Find company<input id=\"search\" type=\"search\" placeholder=\"Company name\"></label></div>\n<nav id=\"filters\" class=\"control-strip\" aria-label=\"Filter companies\"></nav>\n<p id=\"resultCount\"></p><section id=\"researchQueue\" class=\"research-list\" aria-label=\"Companies\"></section><p id=\"researchEmpty\" class=\"empty\" hidden>No companies match this view.</p>\n<details class=\"integration\"><summary>Connections</summary><p>GitHub stores research reports. Shared workflow changes require the Google Sheet connection. HubSpot review is a human confirmation here; this dashboard does not write to HubSpot or send messages.</p></details>\n</main>\n<section id=\"editor\" class=\"review-panel\" hidden aria-label=\"Company review\">\n<div class=\"review-inner\"><div class=\"card-head\"><div><p class=\"eyebrow\">Company review</p><h2 id=\"editTitle\"></h2><p id=\"editStatus\"></p></div><button id=\"close\" type=\"button\">Close</button></div><p id=\"editReason\"></p>\n<form id=\"editForm\"><div class=\"review-layout\"><div class=\"review-main\"><div class=\"report-line\"><strong>Research report</strong><a id=\"reportLink\" target=\"_blank\" rel=\"noreferrer\" hidden>Open on GitHub</a><span id=\"reportMissing\">No report linked</span></div>\n<label>Research summary<textarea name=\"summary\" maxlength=\"4000\" placeholder=\"Verified facts, indicators, and open questions\"></textarea></label><div class=\"crm-check\"><strong>HubSpot check</strong><p id=\"hubspotFinding\"></p></div>\n<div class=\"checks\"><fieldset><legend>Conflict check</legend><label><input name=\"conflicts\" type=\"radio\" value=\"No\">No</label><label><input name=\"conflicts\" type=\"radio\" value=\"Yes\">Yes</label></fieldset><label class=\"check\"><input id=\"qaCheck\" type=\"checkbox\">QA checked</label><label class=\"check\"><input id=\"hubspotCheck\" type=\"checkbox\">Entered into HubSpot and reviewed</label></div>\n<div class=\"draft-heading\"><h3>Message draft</h3><span id=\"draftHint\"></span></div><label>Subject<input name=\"draftSubject\" maxlength=\"4000\"></label><label>Message<textarea name=\"draft\" maxlength=\"4000\" class=\"draft-text\"></textarea></label>\n<details class=\"supporting\"><summary>Research details</summary><div class=\"edit-grid\"><label>Recommended route<input name=\"route\" maxlength=\"4000\"></label><label>Contact / authority findings<input name=\"contact\" maxlength=\"4000\"></label><label class=\"wide\">GitHub report URL<input name=\"report\" type=\"url\" maxlength=\"4000\"></label><label class=\"wide\">Sources and confidence<textarea name=\"sources\" maxlength=\"4000\"></textarea></label><label class=\"wide\">Next action / open questions<textarea name=\"note\" maxlength=\"4000\"></textarea></label></div></details>\n<fieldset id=\"triagePanel\" hidden><legend>Preliminary fit</legend><label>Score<select id=\"triageScore\"><option value=\"\">Not scored</option><option value=\"1\">1 - Poor fit</option><option value=\"2\">2 - Weak fit</option><option value=\"3\">3 - Possible fit</option><option value=\"4\">4 - Strong fit</option><option value=\"5\">5 - Excellent fit</option></select></label><label>Evidence and reason<textarea id=\"triageReason\" maxlength=\"4000\"></textarea></label><button type=\"button\" id=\"saveTriage\">Save score</button></fieldset>\n<p id=\"formError\" role=\"alert\"></p><div class=\"review-actions\"><button id=\"save\" type=\"submit\">Save review</button><button id=\"approve\" type=\"button\" hidden>Approve draft for manual send</button></div><p class=\"approval-note\">Approval never sends a message.</p>\n</div><aside class=\"review-side\"><h3>Review status</h3><p id=\"reviewStatus\"></p><details><summary>Activity history</summary><ol id=\"history\"></ol></details></aside></div></form></div></section>\n<dialog id=\"intakeDialog\"><form id=\"intakeForm\"><div class=\"card-head\"><h2>Add company</h2><button type=\"button\" id=\"closeIntake\">Close</button></div><div class=\"edit-grid\"><label>Company name<input id=\"companyName\" required maxlength=\"200\"></label><label>Company website (optional)<input id=\"companyWebsite\" type=\"url\" placeholder=\"https://\" maxlength=\"2000\"></label><label class=\"wide\">Source details<textarea id=\"intakeSource\" required maxlength=\"4000\"></textarea></label><label>Preliminary fit score<select id=\"intakeScore\"><option value=\"0\">Not scored</option><option value=\"1\">1 - Poor fit</option><option value=\"2\">2 - Weak fit</option><option value=\"3\">3 - Possible fit</option><option value=\"4\">4 - Strong fit</option><option value=\"5\">5 - Excellent fit</option></select></label><label>Score reason<textarea id=\"intakeReason\" maxlength=\"4000\"></textarea></label></div><p id=\"intakeError\" role=\"alert\"></p><button id=\"submitIntake\" type=\"submit\">Add company</button></form></dialog>\n<script src=\"./workflow.js\"></script><script src=\"./app.js\"></script>\n</body></html>\n","type":"text/html; charset=utf-8"},"/styles.css":{"body":":root {\r\n  color-scheme: light;\r\n  --ink: #17212b;\r\n  --muted: #627080;\r\n  --line: #d8dee6;\r\n  --soft: #f2f5f7;\r\n  --panel: #ffffff;\r\n  --accent: #0f6678;\r\n  --accent-dark: #0a4b59;\r\n  --ok: #196f42;\r\n  --hold: #8b5513;\r\n  --danger: #9d302a;\r\n  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\r\n}\r\n\r\n* { box-sizing: border-box; }\r\nbody { margin: 0; background: var(--soft); color: var(--ink); }\r\nbutton, a { -webkit-tap-highlight-color: transparent; }\r\n.topbar { display: flex; justify-content: space-between; gap: 24px; align-items: end; padding: 28px 32px 20px; background: #fff; border-bottom: 1px solid var(--line); }\r\n.eyebrow, .priority, .status { margin: 0 0 6px; color: var(--accent-dark); font-size: 13px; font-weight: 750; text-transform: uppercase; letter-spacing: 0; }\r\nh1, h2, h3, p { margin-top: 0; }\r\nh1 { margin-bottom: 0; font-size: 38px; letter-spacing: 0; }\r\n.summary { display: grid; grid-template-columns: repeat(3, minmax(112px, 1fr)); gap: 10px; }\r\n.summary div { border-left: 3px solid var(--accent); padding: 9px 14px; background: #f8fafb; }\r\n.summary strong { display: block; font-size: 26px; }\r\n.summary span { color: var(--muted); font-size: 13px; }\r\nmain { max-width: 1380px; margin: 0 auto; padding: 20px 24px 48px; }\r\n.control-strip { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 22px; }\r\n.research-gate { display: flex; gap: 12px; align-items: center; margin-bottom: 24px; padding: 13px 15px; border-left: 4px solid var(--accent); background: #eaf3f5; }\r\n.research-gate strong { white-space: nowrap; }\r\n.research-gate span { color: #354653; line-height: 1.4; }\r\nbutton { border: 1px solid var(--line); border-radius: 7px; background: #fff; color: var(--ink); min-height: 40px; padding: 9px 13px; font: inherit; cursor: pointer; }\r\nbutton:hover, button:focus-visible, button.active { border-color: var(--accent); background: #e6f1f3; outline: none; }\r\n.section-header { display: flex; justify-content: space-between; gap: 18px; align-items: end; margin: 18px 0 12px; }\r\n.section-header h2 { margin-bottom: 4px; font-size: 22px; }\r\n.section-header p { color: var(--muted); margin-bottom: 0; font-size: 16px; }\r\n.local-note { color: var(--muted); font-size: 13px; white-space: nowrap; }\r\n.card-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; }\r\n.opportunity-card, .research-row { border: 1px solid var(--line); border-radius: 8px; background: var(--panel); box-shadow: 0 7px 20px rgba(23, 33, 43, .05); }\r\n.opportunity-card { display: flex; flex-direction: column; min-height: 680px; padding: 18px; }\r\n.card-head { display: flex; justify-content: space-between; gap: 14px; }\r\n.card-head h3 { font-size: 21px; margin-bottom: 10px; }\r\n.score { display: inline-flex; align-items: center; justify-content: center; flex: 0 0 auto; height: 34px; min-width: 58px; border-radius: 17px; background: #e7f5ec; color: var(--ok); font-weight: 800; }\r\n.facts { display: grid; gap: 8px; margin: 4px 0 14px; }\r\n.facts div { display: grid; grid-template-columns: 80px 1fr; gap: 10px; padding-bottom: 8px; border-bottom: 1px solid #edf0f4; }\r\ndt { color: var(--muted); font-size: 13px; }\r\ndd { margin: 0; font-size: 14px; line-height: 1.45; }\r\n.draft-box { flex: 1; border: 1px solid #dce6ea; border-radius: 8px; background: #fbfdfe; padding: 12px; }\r\n.subject { margin-bottom: 10px; font-weight: 800; }\r\npre { white-space: pre-wrap; margin: 0; color: #26313c; font: 14px/1.48 ui-monospace, SFMono-Regular, Consolas, \"Liberation Mono\", monospace; }\r\n.actions { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 7px; margin-top: 14px; }\r\n.actions button:first-child { background: var(--accent); border-color: var(--accent); color: #fff; }\r\n.actions button.selected { box-shadow: inset 0 0 0 2px var(--ink); }\r\n.saved-decision { min-height: 20px; margin: 8px 0 0; color: var(--ok); font-size: 13px; font-weight: 700; }\r\n.report-link { margin-top: 4px; color: var(--accent-dark); font-weight: 750; text-decoration: none; }\r\n.report-link:hover { text-decoration: underline; }\r\n.research-heading { margin-top: 34px; }\r\n.research-list { display: grid; gap: 10px; }\r\n.research-row { display: grid; grid-template-columns: 1.2fr 1.3fr 1.7fr auto; align-items: center; gap: 14px; padding: 14px 16px; }\r\n.research-row h3 { margin-bottom: 0; font-size: 18px; }\r\n.research-row p { margin-bottom: 0; color: var(--muted); line-height: 1.4; }\r\n.research-row[data-status=\"hold\"] .score { background: #fff1df; color: var(--hold); }\r\n.empty { padding: 22px; border: 1px dashed var(--line); color: var(--muted); background: #fff; }\r\n\r\n@media (max-width: 1120px) { .card-grid { grid-template-columns: 1fr; } .opportunity-card { min-height: auto; } }\r\n@media (max-width: 820px) { .research-row { grid-template-columns: 1fr; } .local-note { white-space: normal; } }\r\n@media (max-width: 680px) { .topbar, .section-header, .research-gate { display: block; } .research-gate strong { display: block; margin-bottom: 5px; } .topbar { padding: 22px 18px; } .summary { grid-template-columns: 1fr; margin-top: 18px; } main { padding: 18px; } .actions { grid-template-columns: 1fr 1fr; } h1 { font-size: 31px; } }\r\n.connection{display:flex;align-items:center;gap:12px;flex-wrap:wrap;background:white;border:1px solid var(--line);padding:16px;margin-bottom:18px}.connection p{flex:1 1 400px;margin:0;line-height:1.5}\r\n#notice,#formError{color:var(--danger);line-height:1.5}.research-row{grid-template-columns:1.2fr 2fr auto auto}.research-row p+p{margin-top:8px;font-size:14px}.opportunity-card{min-height:0;gap:12px}\r\nbutton:disabled{opacity:.55;cursor:not-allowed}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible{outline:3px solid var(--accent);outline-offset:3px}\r\ninput,select,textarea{display:block;width:100%;font:inherit;color:var(--ink);border:1px solid #8995a0;border-radius:5px;padding:10px;background:#fff;margin-top:6px}label{font-size:14px;font-weight:650}textarea{min-height:95px;resize:vertical}\r\ndialog{width:min(850px,94vw);max-height:90vh;border:1px solid var(--line);border-radius:10px;padding:24px;color:var(--ink)}dialog::backdrop{background:rgba(15,30,40,.55)}.edit-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.wide{grid-column:1/-1}.check{display:flex;align-items:start;gap:10px;line-height:1.5}.check input{width:auto}summary{cursor:pointer;font-weight:650;padding:10px 0}.integration{margin-top:30px;padding:18px;background:white;border:1px solid var(--line)}#history{padding-left:22px;font-size:14px;line-height:1.6;overflow-wrap:anywhere}#save{background:var(--accent);color:white;margin:18px 0}\r\n@media(max-width:820px){.research-row{grid-template-columns:1fr}.research-row .score{justify-self:start}.edit-grid{grid-template-columns:1fr}.section-header{align-items:start;flex-direction:column}}\r\n.intake-start{display:flex;align-items:center;gap:18px;flex-wrap:wrap;background:#fff;border:1px solid var(--line);border-top:4px solid var(--accent);padding:20px;margin:20px 0}.intake-start h2{margin-bottom:6px}.intake-start p{margin-bottom:0}.intake-start>div{flex:1 1 400px}#addOpportunity,#submitIntake{background:var(--accent);color:white}.connection-note{flex-basis:100%;color:var(--muted);font-size:14px}fieldset{margin:22px 0;border:1px solid var(--line);padding:16px}fieldset label{display:block;margin:12px 0}#intakeError{color:var(--danger)}#submitIntake{margin-top:18px}\n.toolbar{display:flex;align-items:end;justify-content:space-between;gap:16px;margin:20px 0}.toolbar label{min-width:min(320px,100%)}#addOpportunity,#save,#approve{background:var(--accent);color:white;border-color:var(--accent)}.row-detail{overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}.review-panel{background:#fff;border-top:2px solid var(--accent);border-bottom:2px solid var(--accent);margin-top:24px;scroll-margin-top:12px}.review-panel[hidden]{display:none}.review-inner{max-width:1380px;margin:auto;padding:28px 24px}.review-layout{display:grid;grid-template-columns:minmax(0,2fr) minmax(210px,1fr);gap:28px}.review-main{display:grid;gap:18px}.review-main label{display:block}.report-line{display:flex;align-items:center;gap:18px;flex-wrap:wrap;padding:12px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.checks{display:flex;flex-wrap:wrap;align-items:center;gap:22px}.checks fieldset{display:flex;align-items:center;gap:16px;margin:0;padding:10px 14px}.checks fieldset label,.checks .check{display:flex;align-items:center;gap:7px}.checks input[type=checkbox],.checks input[type=radio]{width:auto;margin:0}.draft-heading{display:flex;align-items:baseline;gap:16px}.draft-heading h3{margin:0}.draft-heading span{color:var(--muted);font-size:13px}.draft-text{min-height:230px}.review-actions{display:flex;flex-wrap:wrap;gap:10px}.approval-note{font-size:13px;color:var(--muted);margin:0}.review-side{border-left:1px solid var(--line);padding-left:24px}.review-side h3{font-size:17px}.review-side p{line-height:1.5}.supporting{border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.supporting .edit-grid{padding-bottom:18px}.review-panel #save{margin:0}.review-panel #formError{margin:0}.opportunity-card{padding:16px}.card-grid{grid-template-columns:repeat(3,minmax(0,1fr))}\n@media(max-width:820px){.review-layout{grid-template-columns:1fr}.review-side{border-left:0;border-top:1px solid var(--line);padding:18px 0 0}.toolbar{align-items:stretch;flex-direction:column}.checks{align-items:start;flex-direction:column;gap:12px}.card-grid{grid-template-columns:1fr}}\n.crm-check{border-left:3px solid var(--accent);padding:10px 14px;background:#f1f6f7}.crm-check p{margin:5px 0 0;line-height:1.5;color:var(--muted)}\n","type":"text/css"},"/app.js":{"body":"const $ = selector => document.querySelector(selector);\nlet rows = [], seed = [], filter = 'All', mode = 'disconnected', selected = null, busy = false;\nconst PRACTICE_KEY = 'jeff-engine-practice-v4';\nconst text = (tag, value, className) => { const el = document.createElement(tag); el.textContent = value; if (className) el.className = className; return el; };\nconst reportIsValid = url => /^https:\\/\\/github\\.com\\/CoachAGP\\/jeff-outreach-engine\\/blob\\/[^\\s]+$/.test(url || '');\nconst evidenceReady = record => ['route', 'contact', 'summary', 'sources', 'report'].every(key => record[key]?.trim()) && reportIsValid(record.report);\nconst gatesReady = record => evidenceReady(record) && record.conflicts === 'No' && record.qa === 'Pass' && record.hubspotReviewed === 'Yes' && !!record.draftSubject && !!record.draft;\nfunction message(value) { $('#notice').textContent = value; }\nfunction closeEditor() { selected = null; $('#editor').hidden = true; }\nfunction render() {\n  $('#addOpportunity').disabled = mode === 'disconnected';\n  $('#readyCount').textContent = rows.filter(r => r.status === 'Ready for Approval').length;\n  $('#researchCount').textContent = rows.filter(r => ['Researching', 'QA Review'].includes(r.status)).length;\n  $('#filters').replaceChildren();\n  for (const state of ['All', 'Queued', 'Researching', 'QA Review', 'Ready for Approval', 'Approved', 'Hold']) {\n    const count = rows.filter(r => state === 'All' || r.status === state).length;\n    const button = text('button', `${state} (${count})`, filter === state ? 'active' : '');\n    button.onclick = () => { filter = state; closeEditor(); render(); };\n    $('#filters').append(button);\n  }\n  const visible = Workflow.ranked(rows).filter(r => (filter === 'All' || r.status === filter) && r.company.toLowerCase().includes($('#search').value.toLowerCase()));\n  $('#resultCount').textContent = `${visible.length} of ${rows.length} companies · ${mode === 'shared' ? 'Shared queue' : mode === 'practice' ? 'Practice data' : 'Read-only snapshot'}`;\n  $('#researchQueue').replaceChildren();\n  for (const record of visible) {\n    const row = text('article', '', 'research-row');\n    row.dataset.status = record.status.toLowerCase();\n    const heading = text('div', '');\n    heading.append(text('p', record.status, 'status'), text('h3', record.company));\n    const detail = text('p', record.summary || record.reason || 'No research summary yet.', 'row-detail');\n    const score = text('span', record.score ? `${record.score}/5` : 'Unscored', 'score');\n    const button = text('button', 'Review');\n    button.onclick = () => openEditor(record.id);\n    row.append(heading, detail, score, button);\n    $('#researchQueue').append(row);\n  }\n  $('#researchEmpty').hidden = visible.length > 0;\n}\nfunction readForm() {\n  const form = $('#editForm');\n  const patch = {};\n  for (const name of ['route', 'contact', 'report', 'summary', 'sources', 'note', 'draftSubject', 'draft']) patch[name] = form.elements[name].value;\n  patch.conflicts = form.querySelector('input[name=\"conflicts\"]:checked')?.value || '';\n  patch.qa = $('#qaCheck').checked ? 'Pass' : '';\n  patch.hubspotReviewed = $('#hubspotCheck').checked ? 'Yes' : '';\n  patch.draftStatus = patch.draft.trim() ? 'Draft awaiting separate approval' : 'Not drafted';\n  return patch;\n}\nfunction updateReviewStatus() {\n  if (!selected) return;\n  const candidate = {...selected, ...readForm()};\n  const draft = Workflow.draftFor(candidate);\n  if (draft && !candidate.draftSubject && !candidate.draft) {\n    $('#editForm').elements.draftSubject.value = draft.draftSubject;\n    $('#editForm').elements.draft.value = draft.draft;\n    $('#draftHint').textContent = 'Created from research. Review before approval.';\n    candidate.draftSubject = draft.draftSubject;\n    candidate.draft = draft.draft;\n  } else if (!draft) $('#draftHint').textContent = 'Add research details to generate a draft.';\n  const missing = [];\n  if (!evidenceReady(candidate)) missing.push('research details and GitHub report');\n  if (candidate.conflicts !== 'No') missing.push('no-conflict check');\n  if (candidate.qa !== 'Pass') missing.push('QA check');\n  if (candidate.hubspotReviewed !== 'Yes') missing.push('HubSpot entry and review');\n  if (!candidate.draftSubject || !candidate.draft) missing.push('message draft');\n  $('#reviewStatus').textContent = selected.status === 'Approved' ? 'Approved for manual send. No message has been sent.' : missing.length ? `Still needed: ${missing.join(', ')}.` : 'All checks complete. Save review, then Jeff can approve the draft.';\n  $('#approve').hidden = selected.status !== 'Ready for Approval';\n  $('#approve').disabled = mode === 'disconnected' || busy;\n}\nfunction openEditor(id) {\n  selected = rows.find(r => r.id === id);\n  const record = selected;\n  $('#editTitle').textContent = record.company;\n  $('#editStatus').textContent = `${record.status} · Preliminary fit ${record.score || 'unscored'}/5`;\n  $('#editReason').textContent = record.reason || '';\n  $('#hubspotFinding').textContent = record.hubspotFinding || 'Not checked in this workspace. Jeff must verify the company in his HubSpot account.';\n  for (const name of ['route', 'contact', 'report', 'summary', 'sources', 'note', 'draftSubject', 'draft']) $('#editForm').elements[name].value = record[name] || '';\n  for (const radio of $('#editForm').querySelectorAll('input[name=\"conflicts\"]')) radio.checked = radio.value === record.conflicts;\n  $('#qaCheck').checked = record.qa === 'Pass';\n  $('#hubspotCheck').checked = record.hubspotReviewed === 'Yes';\n  $('#reportLink').hidden = !reportIsValid(record.report);\n  $('#reportMissing').hidden = reportIsValid(record.report);\n  if (reportIsValid(record.report)) $('#reportLink').href = record.report;\n  $('#formError').textContent = '';\n  $('#draftHint').textContent = '';\n  $('#history').replaceChildren();\n  for (const item of record.history || []) $('#history').append(text('li', `${item.at} · ${item.actor} · ${item.from} to ${item.to}: ${item.note}`));\n  $('#triagePanel').hidden = record.status !== 'Hold';\n  $('#triageScore').value = record.score || '';\n  $('#triageReason').value = record.reason || '';\n  const locked = mode === 'disconnected' || ['Approved', 'Hold'].includes(record.status);\n  for (const field of $('#editForm').querySelectorAll('input, textarea, select')) field.disabled = locked;\n  $('#save').disabled = locked;\n  for (const field of $('#triagePanel').querySelectorAll('input, textarea, select, button')) field.disabled = mode === 'disconnected';\n  $('#editor').hidden = false;\n  updateReviewStatus();\n  $('#editor').scrollIntoView({behavior:'smooth', block:'start'});\n}\nasync function refresh() {\n  if (busy) return;\n  busy = true; $('#refresh').disabled = true;\n  try {\n    const response = await fetch('/api/queue', {cache:'no-store'});\n    const result = await response.json();\n    if (!response.ok || result.error || !Array.isArray(result.rows)) throw Error(result.error || 'Connection unavailable.');\n    rows = result.rows; mode = 'shared'; $('#connection').textContent = `Shared Google Sheet connected · refreshed ${new Date().toLocaleTimeString()}`;\n    $('#exitDemo').hidden = true; message('');\n  } catch (error) {\n    if (mode !== 'practice') { rows = seed; mode = 'disconnected'; }\n    $('#connection').textContent = `Shared queue not connected. ${error.message}`;\n  } finally { busy = false; $('#refresh').disabled = false; closeEditor(); render(); }\n}\nasync function saveOperation(action, command, next) {\n  if (mode === 'practice') { localStorage.setItem(PRACTICE_KEY, JSON.stringify(next)); rows = next; }\n  else if (mode === 'shared') {\n    const response = await fetch('/api/' + action, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(command)});\n    const result = await response.json();\n    if (!response.ok || result.error || !Array.isArray(result.rows)) throw Error(result.error || 'Save not confirmed. Refresh before retrying.');\n    rows = result.rows;\n  } else throw Error('Connect the shared queue or enter practice mode before saving.');\n}\nasync function transition(to, patch = {}) {\n  const command = {id:selected.id, revision:selected.revision, to, patch, humanConfirmed:to === 'Approved', requestId:crypto.randomUUID()};\n  const next = Workflow.apply(rows, command, mode === 'practice' ? 'Practice reviewer' : 'Jeff');\n  await saveOperation('transition', command, next);\n  const id = selected.id;\n  render(); openEditor(id);\n}\n$('#editForm').oninput = updateReviewStatus;\n$('#editForm').onchange = updateReviewStatus;\n$('#editForm').onsubmit = async event => {\n  event.preventDefault(); if (busy || !selected) return;\n  busy = true; $('#save').disabled = true;\n  try {\n    const patch = readForm();\n    const candidate = {...selected, ...patch};\n    const to = gatesReady(candidate) ? 'Ready for Approval' : evidenceReady(candidate) ? 'QA Review' : selected.status === 'Ready for Approval' ? 'QA Review' : selected.status;\n    await transition(to, patch);\n    message(mode === 'practice' ? 'Practice review saved on this device.' : 'Review saved to the shared queue.');\n  } catch (error) { $('#formError').textContent = error.message; }\n  finally { busy = false; $('#save').disabled = mode === 'disconnected' || ['Approved', 'Hold'].includes(selected?.status); updateReviewStatus(); }\n};\n$('#approve').onclick = async () => {\n  if (busy || !selected || !confirm('Approve this draft for manual sending? No message will be sent by the dashboard.')) return;\n  busy = true; $('#approve').disabled = true;\n  try { await transition('Approved'); message('Draft approved for manual send. No communication was sent.'); }\n  catch (error) { $('#formError').textContent = error.message; }\n  finally { busy = false; updateReviewStatus(); }\n};\n$('#close').onclick = closeEditor;\n$('#search').oninput = () => { closeEditor(); render(); };\n$('#refresh').onclick = refresh;\n$('#demo').onclick = () => {\n  if (busy) return;\n  try { rows = JSON.parse(localStorage.getItem(PRACTICE_KEY) || JSON.stringify(seed)); if (!Array.isArray(rows)) throw Error(); }\n  catch { rows = structuredClone(seed); }\n  mode = 'practice'; $('#connection').textContent = 'Practice mode · changes stay on this device.';\n  $('#exitDemo').hidden = false; message('Practice changes do not sync to Jeff.'); closeEditor(); render();\n};\n$('#exitDemo').onclick = () => { mode = 'disconnected'; refresh(); };\n$('#researchQueue').after($('#editor'));\n$('#addOpportunity').onclick = () => { $('#intakeForm').reset(); $('#intakeSource').value = 'Manual entry'; $('#intakeError').textContent = ''; $('#intakeDialog').showModal(); };\n$('#closeIntake').onclick = () => $('#intakeDialog').close();\n$('#intakeForm').onsubmit = async event => {\n  event.preventDefault(); if (busy) return; busy = true;\n  const command = {company:$('#companyName').value, website:$('#companyWebsite').value, source:$('#intakeSource').value, score:Number($('#intakeScore').value), reason:$('#intakeReason').value, requestId:crypto.randomUUID()};\n  try { const next = Workflow.intake(rows, command, 'Jeff'); await saveOperation('intake', command, next); $('#intakeDialog').close(); filter = 'All'; $('#search').value = command.company.trim(); render(); message('Company added.'); }\n  catch (error) { $('#intakeError').textContent = error.message; }\n  finally { busy = false; }\n};\n$('#saveTriage').onclick = async () => {\n  if (busy || !selected) return; busy = true;\n  const command = {id:selected.id, revision:selected.revision, score:Number($('#triageScore').value), reason:$('#triageReason').value, requestId:crypto.randomUUID()};\n  try { const next = Workflow.triage(rows, command, 'Jeff'); await saveOperation('triage', command, next); const id=selected.id; render(); openEditor(id); message('Preliminary score saved.'); }\n  catch (error) { $('#formError').textContent = error.message; }\n  finally { busy = false; }\n};\n(async () => { try { const response = await fetch('./seed.json'); if (!response.ok) throw Error(); seed = await response.json(); await refresh(); } catch { message('Could not load the company snapshot. Reload the dashboard.'); } })();\n","type":"text/javascript"},"/workflow.js":{"body":"/* Shared by the browser preview and the authoritative Sheet adapter. */\r\nconst Workflow = (() => {\r\n  const states = ['Queued', 'Researching', 'QA Review', 'Ready for Approval', 'Approved', 'Hold'];\r\n  const edges = {'Queued':['Researching','QA Review','Ready for Approval','Hold'], 'Researching':['QA Review','Ready for Approval','Hold'], 'QA Review':['Researching','Ready for Approval','Hold'], 'Ready for Approval':['Researching','QA Review','Approved','Hold'], 'Approved':['Hold'], 'Hold':['Queued']};\n  const fields = ['route','contact','report','summary','sources','conflicts','qa','hubspotReviewed','draftSubject','draft','note','draftStatus'];\n  const eligible = r => Number.isInteger(r.score) && r.score >= 3 && r.score <= 5;\r\n  const ranked = rows => [...rows].sort((a,b) => b.score-a.score || a.company.localeCompare(b.company));\r\n  const normalizeName = value => value.trim().toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();\n  function draftFor(record) {\n    if (!['route','contact','summary','sources','report'].every(key => record[key]?.trim())) return null;\n    return {\n      draftSubject: `Quick question about ${record.company}`,\n      draft: `Hello,\\n\\nI work with ERA Group to help organizations review indirect supplier spend with category expertise, no upfront cost, and no obligation.\\n\\nWould you be the right person to ask whether a brief conversation about ${record.company}'s operating spend would be relevant, or is there someone else on the finance or operations side I should contact?\\n\\nI am not assuming savings exist. I would simply welcome a quick routing conversation.\\n\\nThanks,\\nJeff Peduto`\n    };\n  }\n  function intake(rows, cmd, actor, now = new Date().toISOString()) {\r\n    if (!actor || typeof cmd.requestId !== 'string' || !/^[\\w-]{1,100}$/.test(cmd.requestId)) throw Error('Reviewer and valid request ID required.');\r\n    if (rows.some(r => r.history.some(h => h.requestId === cmd.requestId))) return rows;\r\n    const company = typeof cmd.company === 'string' ? cmd.company.trim() : '';\r\n    if (!company || company.length > 200 || !normalizeName(company)) throw Error('Enter a company name of at most 200 characters.');\r\n    if (rows.some(r => normalizeName(r.company) === normalizeName(company))) throw Error('This company is already in the queue. Search and open its existing record.');\r\n    const website = typeof cmd.website === 'string' ? cmd.website.trim() : '';\r\n    if (website && !/^https:\\/\\/[a-z0-9.-]+(?::\\d+)?(?:[/?#][^\\s]*)?$/i.test(website)) throw Error('Use a complete HTTPS company website URL.');\r\n    for (const field of ['source','reason']) if (typeof cmd[field] !== 'string' || cmd[field].length > 4000) throw Error('Source and score reason must be text of at most 4,000 characters.');\r\n    if (!cmd.source.trim()) throw Error('Record where this opportunity came from.');\r\n    const score = cmd.score;\r\n    if (!Number.isInteger(score) || score < 0 || score > 5) throw Error('Choose a preliminary score from 1 to 5, or leave unscored.');\r\n    if (score && !cmd.reason.trim()) throw Error('Explain the preliminary score using available evidence.');\r\n    const status = score >= 3 ? 'Queued' : 'Hold';\r\n    const record = {id:'intake-'+cmd.requestId, company, website, score, status, reason:cmd.reason.trim() || 'Not scored. Preliminary review required.', route:'', contact:'', report:'', summary:'', sources:cmd.source.trim(), conflicts:'', qa:'', hubspotReviewed:'', draftSubject:'', draft:'', note:score>=3?'Research candidate.':'Assign a preliminary score before research.', revision:0, draftStatus:'Not drafted', history:[{requestId:cmd.requestId, at:now, actor, from:'Intake', to:status, note:'Company added; source data is unverified until checked.'}]};\n    return [...rows,record];\r\n  }\r\n  function triage(rows, cmd, actor, now = new Date().toISOString()) {\r\n    const old = rows.find(r => r.id === cmd.id);\r\n    if (!old || !actor || typeof cmd.requestId !== 'string') throw Error('Company, reviewer and request ID required.');\r\n    if (old.history.some(h=>h.requestId===cmd.requestId)) return rows;\r\n    if (old.revision !== cmd.revision) throw Error('This company changed in another session. Refresh before saving.');\r\n    if (!['Hold','Queued'].includes(old.status)) throw Error('Preliminary scoring is available only before active research or while on hold.');\r\n    if (!Number.isInteger(cmd.score) || cmd.score<1 || cmd.score>5 || typeof cmd.reason!=='string' || !cmd.reason.trim() || cmd.reason.length>4000) throw Error('Provide a score from 1 to 5 and an evidence-based reason.');\r\n    // A revised score does not release an existing hold; human review remains separate.\r\n    const status=old.status==='Hold'||cmd.score<3?'Hold':'Queued';\r\n    const next={...old,score:cmd.score,reason:cmd.reason.trim(),status,revision:old.revision+1,history:[...old.history,{requestId:cmd.requestId,at:now,actor,from:old.status,to:status,note:'Preliminary score '+old.score+' → '+cmd.score+': '+cmd.reason.trim()}]};\r\n    return rows.map(r=>r.id===next.id?next:r);\r\n  }\r\n  function apply(rows, cmd, actor, now = new Date().toISOString()) {\r\n    const index = rows.findIndex(r => r.id === cmd.id);\r\n    if (index < 0) throw Error('Company not found. Refresh the queue.');\r\n    const old = rows[index];\r\n    if (typeof cmd.note !== 'undefined' && (typeof cmd.note !== 'string' || cmd.note.length > 4000)) throw Error('Decision note must be text of at most 4,000 characters.');\r\n    if (!actor || !cmd.requestId || typeof cmd.requestId !== 'string') throw Error('Reviewer and request ID are required.');\r\n    if (old.history.some(h => h.requestId === cmd.requestId)) return rows;\r\n    if (cmd.revision !== old.revision) throw Error('This company changed in another session. Refresh before saving.');\r\n    if (cmd.to !== old.status && !(edges[old.status] || []).includes(cmd.to)) throw Error('That workflow transition is not allowed.');\r\n    if (!states.includes(cmd.to)) throw Error('Unknown workflow status.');\r\n    const next = {...old};\r\n    for (const key of Object.keys(cmd.patch || {})) {\r\n      if (!fields.includes(key)) throw Error('Unsupported field: '+key);\r\n      if (typeof cmd.patch[key] !== 'string' || cmd.patch[key].length > 4000) throw Error('Each field must be text of at most 4,000 characters.');\r\n      next[key] = cmd.patch[key].trim();\r\n    }\r\n    if (['Approved','Ready for Approval'].includes(old.status) && !['Researching','QA Review','Hold'].includes(cmd.to) && fields.some(k => next[k] !== old[k])) throw Error('Return to review before changing approved evidence.');\n    if (cmd.to !== 'Hold' && !eligible(next)) throw Error('Only preliminary scores 3–5 qualify. Scores 1–2 stay on hold.');\r\n    if (cmd.to === 'Researching' && old.status === 'Queued') {\r\n      const higher = rows.find(r => r.status === 'Queued' && eligible(r) && r.score > next.score);\r\n      if (higher) throw Error('Activate queued score '+higher.score+' companies first. Priority is 5, then 4, then 3.');\r\n    }\r\n    if (['QA Review','Ready for Approval','Approved'].includes(cmd.to)) {\r\n      for (const k of ['route','contact','summary','sources','report']) if (!next[k]) throw Error('Complete '+k+' before QA review.');\r\n      if (!/^https:\\/\\/github\\.com\\/CoachAGP\\/jeff-outreach-engine\\/blob\\/[^\\s]+$/.test(next.report)) throw Error('Link the research report committed to the project GitHub repository.');\r\n    }\r\n    if (['Ready for Approval','Approved'].includes(cmd.to)) {\n      if (next.qa !== 'Pass' || next.conflicts !== 'No' || next.hubspotReviewed !== 'Yes' || !next.draftSubject || !next.draft) throw Error('QA, no conflict, HubSpot entry/review, and a complete draft are required before approval.');\n    }\n    if (cmd.to === 'Approved' && !cmd.humanConfirmed) throw Error('Jeff must explicitly approve the draft for manual sending.');\n    if (cmd.to === 'Hold' && !cmd.note?.trim()) throw Error('Explain the hold and what must be resolved.');\r\n    if (old.status === 'Hold' && cmd.to === 'Queued' && (!cmd.humanConfirmed || !cmd.note?.trim())) throw Error('Confirm human review and explain why the hold is resolved.');\r\n    next.status = cmd.to;\r\n    if (cmd.to === 'Researching' && old.status !== 'Researching') next.qa = '';\r\n    next.revision = old.revision + 1;\r\n    next.history = [...old.history, {requestId:cmd.requestId, at:now, actor, from:old.status, to:next.status, note:cmd.note || 'Research fields updated', changes:Object.fromEntries(fields.filter(k=>old[k]!==next[k]).map(k=>[k,{from:old[k],to:next[k]}]))}];\r\n    return rows.map((r,i) => i===index ? next : r);\r\n  }\r\n  return {states, edges, eligible, ranked, intake, triage, apply, draftFor};\n})();\r\nif (typeof module !== 'undefined') module.exports = Workflow;\r\n","type":"text/javascript"},"/seed.json":{"body":"[\n  {\n    \"id\": \"accede-mold-tool\",\n    \"company\": \"Accede Mold & Tool\",\n    \"website\": \"https://accedemold.com/\",\n    \"score\": 4,\n    \"status\": \"QA Review\",\n    \"reason\": \"Strong manufacturing fit; revenue and current urgency are not verified, so the earlier 5/5 is revised to 4/5.\",\n    \"route\": \"Possible direct owner/president route; Jeff must confirm contact and any warm path.\",\n    \"contact\": \"Roger Fox, described in Accede company sources as owner/president; current channel not confirmed.\",\n    \"report\": \"https://github.com/CoachAGP/jeff-outreach-engine/blob/main/docs/discovery/opportunity-report-accede-mold-tool.md\",\n    \"summary\": \"Verified: precision moldmaking and systems integration in Rochester, NY. Earlier ZoomInfo Cost Control score 99 is an undated source-provided indicator, not confirmed current buying intent. Indirect supplier categories are hypotheses. Joe HubSpot had no company match; Jeff's conflict check is pending.\",\n    \"sources\": \"https://accedemold.com/about-us/ (company, leadership); https://accedemold.com/plastics_fall_conference_2023/ (Roger Fox role); prior ZoomInfo intent email (undated indicator). Checked 2026-09-22.\",\n    \"conflicts\": \"\",\n    \"qa\": \"Pass\",\n    \"hubspotReviewed\": \"\",\n    \"hubspotFinding\": \"Connected Joe HubSpot: no company match by name or domain; no named-contact match. Jeff's HubSpot and Athena not checked. No record written.\",\n    \"draftSubject\": \"Quick question about Accede Mold & Tool\",\n    \"draft\": \"Hello Roger,\\n\\nI work with ERA Group, helping organizations review indirect supplier spend with deep category expertise and no upfront cost. I came across Accede's work in precision moldmaking and systems integration and thought there might be a useful conversation.\\n\\nAre you the right person to ask whether a brief discussion about operating supplier costs would be relevant, or would someone on your finance or operations team be better?\\n\\nBest,\\nJeff Peduto\",\n    \"draftStatus\": \"Draft awaiting separate approval\",\n    \"note\": \"Confirm Roger's current role/channel; Jeff must check his HubSpot and Athena, resolve conflict status, and approve any communication.\",\n    \"revision\": 0,\n    \"history\": [{\"requestId\":\"pilot-accede-20260922\",\"at\":\"2026-09-22T16:07:00Z\",\"actor\":\"Codex (Joe workspace)\",\"from\":\"Pilot intake\",\"to\":\"QA Review\",\"note\":\"Sourced report and draft prepared; Jeff checks pending.\"}]\n  },\n  {\n    \"id\": \"delcath-systems\",\n    \"company\": \"Delcath Systems\",\n    \"website\": \"https://delcath.com/\",\n    \"score\": 5,\n    \"status\": \"QA Review\",\n    \"reason\": \"U.S. healthcare manufacturer with reported $29.1M Q2 2026 revenue and a current commercial expansion signal; indirect spend remains unverified.\",\n    \"route\": \"Possible direct finance route; Jeff must confirm contact and relationship status.\",\n    \"contact\": \"Sandra Pennell, CFO identified in August 2026 SEC filing; contact channel not confirmed.\",\n    \"report\": \"https://github.com/CoachAGP/jeff-outreach-engine/blob/main/docs/discovery/opportunity-report-delcath-systems.md\",\n    \"summary\": \"Verified: Delcath reported $29.1M Q2 2026 revenue and 31 active treatment centers. The September 12 ZoomInfo lists estimate 156 employees and $95.418M revenue; they contain no specific intent score. Joe HubSpot had no company match; Jeff's conflict check is pending.\",\n    \"sources\": \"https://investors.delcath.com/news-releases/news-release-details/delcath-systems-reports-second-quarter-2026-results-and-business (Q2 results); https://investors.delcath.com/node/19131/html (CFO); user-supplied Sept 12 ZoomInfo CSVs, ID 10879082. Checked 2026-09-22.\",\n    \"conflicts\": \"\",\n    \"qa\": \"Pass\",\n    \"hubspotReviewed\": \"\",\n    \"hubspotFinding\": \"Connected Joe HubSpot: no company match by name or domain; no named-contact match. Jeff's HubSpot and Athena not checked. No record written.\",\n    \"draftSubject\": \"Quick question about Delcath\",\n    \"draft\": \"Hello Sandra,\\n\\nI work with ERA Group, helping organizations review indirect supplier spend with deep category expertise and no upfront cost. I saw Delcath's recent update on its expanding treatment-center network and thought a short finance-side conversation might be useful.\\n\\nAre you the right person to ask whether a discussion about operating supplier costs would be relevant, or is there someone else on your team I should speak with?\\n\\nBest,\\nJeff Peduto\",\n    \"draftStatus\": \"Draft awaiting separate approval\",\n    \"note\": \"Confirm CFO role/channel; Jeff must check his HubSpot and Athena, resolve conflict status, and approve any communication.\",\n    \"revision\": 0,\n    \"history\": [{\"requestId\":\"pilot-delcath-20260922\",\"at\":\"2026-09-22T16:07:00Z\",\"actor\":\"Codex (Joe workspace)\",\"from\":\"Pilot intake\",\"to\":\"QA Review\",\"note\":\"Sourced report and draft prepared; Jeff checks pending.\"}]\n  },\n  {\n    \"id\": \"angiodynamics\",\n    \"company\": \"AngioDynamics\",\n    \"website\": \"https://www.angiodynamics.com/\",\n    \"score\": 5,\n    \"status\": \"QA Review\",\n    \"reason\": \"U.S. medical-technology manufacturing fit; company-reported $320.2M FY2026 pro forma sales and Med Tech growth, with indirect spend still unverified.\",\n    \"route\": \"Possible direct finance route; Jeff must confirm contact and relationship status.\",\n    \"contact\": \"Stephen Trowbridge, EVP and CFO in June 2026 company release; current channel not confirmed.\",\n    \"report\": \"https://github.com/CoachAGP/jeff-outreach-engine/blob/main/docs/discovery/opportunity-report-angiodynamics.md\",\n    \"summary\": \"Verified: AngioDynamics reported $320.2M FY2026 pro forma net sales and $150.0M Med Tech sales. The September 12 ZoomInfo lists estimate 632 employees but provide no specific intent score. Joe HubSpot had no exact-domain company match; Jeff's conflict check is pending.\",\n    \"sources\": \"https://investors.angiodynamics.com/news-releases/news-release-details/angiodynamics-reports-record-fiscal-year-2026-fourth-quarter-and (FY2026 results); https://investors.angiodynamics.com/node/23481 (CFO); user-supplied Sept 12 ZoomInfo CSVs, ID 15569419. Checked 2026-09-22.\",\n    \"conflicts\": \"\",\n    \"qa\": \"Pass\",\n    \"hubspotReviewed\": \"\",\n    \"hubspotFinding\": \"Connected Joe HubSpot: no exact-domain company match; no named-contact match. Jeff's HubSpot and Athena not checked. No record written.\",\n    \"draftSubject\": \"Quick question about AngioDynamics\",\n    \"draft\": \"Hello Stephen,\\n\\nI work with ERA Group, helping organizations review indirect supplier spend with deep category expertise and no upfront cost. I saw AngioDynamics' recent fiscal-year update and its Med Tech growth and thought there might be a useful finance-side conversation.\\n\\nAre you the right person to ask whether a brief discussion about operating supplier costs would be relevant, or would someone else on your team be better?\\n\\nBest,\\nJeff Peduto\",\n    \"draftStatus\": \"Draft awaiting separate approval\",\n    \"note\": \"Confirm CFO role/channel; Jeff must check his HubSpot and Athena, resolve conflict status, and approve any communication.\",\n    \"revision\": 0,\n    \"history\": [{\"requestId\":\"pilot-angio-20260922\",\"at\":\"2026-09-22T16:07:00Z\",\"actor\":\"Codex (Joe workspace)\",\"from\":\"Pilot intake\",\"to\":\"QA Review\",\"note\":\"Sourced report and draft prepared; Jeff checks pending.\"}]\n  }\n]\n","type":"application/json"}};
// Private Sites dispatch supplies authenticated identity. Never expose the bridge key to the browser.
export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (!url.pathname.startsWith('/api/')) { const path=url.pathname==='/'?'/index.html':url.pathname; const asset=ASSETS[path]; return asset?new Response(asset.body,{headers:{'Content-Type':asset.type,'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}}):new Response('Not found',{status:404}); }
    const headers = {'Content-Type':'application/json','Cache-Control':'no-store'};
    const reply = (value,status=200) => new Response(JSON.stringify(value),{status,headers});
    const actor = request.headers.get('oai-authenticated-user-email');
    const allowed = (env.REVIEWER_EMAILS || '').toLowerCase().split(',').map(s=>s.trim()).filter(Boolean);
    if (!actor || !allowed.includes(actor.toLowerCase())) return reply({error:'Reviewer access has not been configured for this account.'},403);
    if (!env.SHEETS_BRIDGE_URL || !env.SHEETS_BRIDGE_KEY) return reply({error:'Shared Google Sheet is not connected. Jeff must authorize the Sheet bridge.'},503);
    if (!/^https:\/\/script\.google\.com\/macros\/s\/[\w-]+\/exec$/.test(env.SHEETS_BRIDGE_URL)) return reply({error:'Sheet connection configuration is invalid.'},503);
    let command;
    if (request.method === 'POST' && ['/api/transition','/api/intake','/api/triage'].includes(url.pathname)) {
      if (request.headers.get('Origin') !== url.origin || !request.headers.get('Content-Type')?.startsWith('application/json')) return reply({error:'Invalid request origin or format.'},403);
      const body = await request.text();
      if (body.length > 40000) return reply({error:'Update is too large.'},413);
      try { command = JSON.parse(body); } catch { return reply({error:'Invalid update.'},400); }
    } else if (!(request.method === 'GET' && url.pathname === '/api/queue')) return reply({error:'Not found'},404);
    try {
      const upstream = await fetch(env.SHEETS_BRIDGE_URL,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:env.SHEETS_BRIDGE_KEY,actor,action:command?url.pathname.slice(5):'list',command}),signal:AbortSignal.timeout(20000)});
      if (!upstream.ok) throw Error('bridge unavailable');
      const result = await upstream.json();
      return reply(result,result.error?409:200);
    } catch { return reply({error:'Could not confirm the Sheet response. Refresh before retrying; no local success was recorded.'},502); }
  }
};
